;                 vendored as assets/gfx/source/wazhack_sprites.dc.html
;                 artboard: KEY / KEY (8x8), ink #FFFF00
;                 grid: assets/gfx/sprites/grid/item_key.grid (via tools/svg_sprites.py)
; Dimensions    : 8x8 px = 1 data cols x 8 rows, no pad col (engine pre-shift spills into col 1)
; Layout/row    : c0_mask,c0_data  (MSB=left)
; Mask polarity : bit 1 = transparent (keep background)
; Mask shape    : filled silhouette (+ outline if any) — enclosed paper is opaque
; Composite     : screen = (screen AND mask) OR data
; Bytes         : 8*2 + 1 descriptor = 17
; Colour        : ink=yellow paper=black bright=1  -> ATTR_SPRITE=$46
; Band paper    : black (descriptor PAPER must match — verified)
; Intended use  : engine boot-gen of 8 pre-shifts; masked blit at pixel X
; Anchor        : ax=0 ay=0  draw_x = body_x - ax, draw_y = body_y - ay (right-facing; body_x/y = reference frame origin)
; ============================================================================
item_key:
        DEFB $0F,$00    ; row  0
        DEFB $07,$60    ; row  1
        DEFB $00,$90    ; row  2
        DEFB $00,$9F    ; row  3
        DEFB $00,$65    ; row  4
        DEFB $00,$00    ; row  5
        DEFB $FF,$00    ; row  6
        DEFB $FF,$00    ; row  7
item_key_attr:
        DEFB $46                                  ; ATTR_SPRITE
item_key_len  EQU $ - item_key
item_key_w    EQU 8                ; px
item_key_h    EQU 8                ; px (rows)
item_key_cols EQU 1                 ; byte columns (x2 bytes each)
item_key_ax   EQU 0                 ; x-anchor, px left of body origin
item_key_ay   EQU 0                 ; y-anchor, px above body origin
